('advanced-native-822', '["phrase"]'::jsonb, '{"advanced-native-822-v1-audio":{"type":"mc","answers":["Current income meets immediate needs but leaves little financial buffer."],"options":["Their shifts provide a stable surplus after everyday expenses.","Current income meets immediate needs but leaves little financial buffer.","They have no work or earnings of any kind.","They have substantial savings set aside for unexpected costs."]},"advanced-native-822-v2-reply":{"type":"mc","answers":["Their income covers basic costs with very little left over.","They are living from hand to mouth.","Irregular shifts make it hard to build a financial buffer.","Food and rent already use most of what they earn."],"options":["Their income covers basic costs with very little left over.","They are living from hand to mouth.","Irregular shifts make it hard to build a financial buffer.","Food and rent already use most of what they earn."]},"advanced-native-822-v1-scene":{"type":"mc","answers":["They are living from hand to mouth despite being in work."],"options":["Their regular surplus lets them save comfortably after basic costs.","They have no employment, so there is no income at all.","They are living from hand to mouth despite being in work."]},"advanced-native-822-v1-contrast":{"type":"mc","answers":["The person must be unemployed or careless with money."],"options":["The person must be unemployed or careless with money.","An unexpected cost may be hard to absorb.","There is little room beyond immediate needs."]},"advanced-native-822-v1-branch":{"type":"mc","answers":["Say they are living from hand to mouth and describe the income and costs you know, without inventing a cause."],"options":["Keep the claim about effort and leave out the evidence about irregular shifts.","Change the description to unemployment even though the records show paid work.","Say they are living from hand to mouth and describe the income and costs you know, without inventing a cause."]},"advanced-native-8