('advanced-native-864', '["phrase"]'::jsonb, '{"advanced-native-864-v1-audio":{"type":"mc","answers":["They located the places indicated by their ticket details."],"options":["They bought tickets for the first time after entering the row.","They reserved the whole row for a future event rather than locating a place now.","They chose the nearest empty chairs without consulting the numbers.","They located the places indicated by their ticket details."]},"advanced-native-864-v2-reply":{"type":"mc","answers":["The row and seat details guided us to the right places.","We checked the labels against the numbers printed on our tickets.","We matched the ticket numbers with the row signs.","We used the signs to find our seats."],"options":["The row and seat details guided us to the right places.","We checked the labels against the numbers printed on our tickets.","We matched the ticket numbers with the row signs.","We used the signs to find our seats."]},"advanced-native-864-v1-scene":{"type":"mc","answers":["I found my seat by checking the name cards."],"options":["I took my seat and started lunch before checking the name cards.","I found my seat by checking the name cards.","I reserved a place by putting my bag on an unlabelled chair."]},"advanced-native-864-v1-contrast":{"type":"mc","answers":["The people necessarily bought or reserved the tickets at that moment."],"options":["The people necessarily bought or reserved the tickets at that moment.","They may use labels, numbers or an usher’s guidance to locate the places.","The people located the places intended for them."]},"advanced-native-864-v1-branch":{"type":"mc","answers":["Let us find our seats using the ticket numbers before choosing an empty chair."],"options":["Let us find our seats using the ticket numbers before choosing an empty chair.","Let us sit in the nearest empty chairs and check our ticket numbers later.","Ask to reserve new seats before checking where the existing tickets already place us."]},"advanced-